import{_ as l}from"./chunks/44.D4GIdpL8.js";import{_ as a,a as i}from"./chunks/0.C2kxRHFx.js";import{_ as c}from"./chunks/1._Wu06lVH.js";import{_ as e}from"./chunks/0.xVPDiwtD.js";import{_ as d}from"./chunks/2.9ug2zROR.js";import{_ as p}from"./chunks/11.H1duxI87.js";import{_ as g}from"./chunks/11.DiIhyeL-.js";import{_ as r}from"./chunks/0.B7TrDeTt.js";import{_ as h}from"./chunks/12.D1pIPcbk.js";import{_ as m}from"./chunks/1.BU1qyW7B.js";import{_ as o}from"./chunks/0.DyB7G7H5.js";import{_ as u}from"./chunks/3.PcdR27wg.js";import{_ as f}from"./chunks/4.ZpmvUIOM.js";import{_ as b}from"./chunks/100.DMbJtyMU.js";import{_ as y}from"./chunks/community.BdKwbEUF.js";import{_,C as w,o as v,c as k,ak as n,E as x}from"./chunks/framework.sbZkgmEx.js";const q="/projects/AiBlock/en/advanced-kit/assets/1.B3016j0q.webp",P="/projects/AiBlock/en/advanced-kit/assets/2.1.spV0OpNX.webp",A="/projects/AiBlock/en/advanced-kit/assets/2.CsRwh8A0.webp",z="/projects/AiBlock/en/advanced-kit/assets/3.CaSMD4A0.webp",T="/projects/AiBlock/en/advanced-kit/assets/4.DnF2XCU-.webp",Y=JSON.parse('{"title":"3.44 Tank Robotic Arm","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.44 Tank Robotic Arm.md","filePath":"docs/3.Creative Builds/3.44 Tank Robotic Arm.md"}'),S={name:"docs/3.Creative Builds/3.44 Tank Robotic Arm.md"};function j(C,t,B,I,O,R){const s=w("Pdf");return v(),k("div",null,[t[0]||(t[0]=n('<h1 id="_3-44-tank-robotic-arm" tabindex="-1">3.44 Tank Robotic Arm <a class="header-anchor" href="#_3-44-tank-robotic-arm" aria-label="Permalink to &quot;3.44 Tank Robotic Arm&quot;">​</a></h1><h2 id="_3-44-1-lesson-introduction" tabindex="-1">3.44.1 Lesson Introduction <a class="header-anchor" href="#_3-44-1-lesson-introduction" aria-label="Permalink to &quot;3.44.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on a multi-functional robotic arm platform, this lesson explores coordinated programming among a tracked chassis, dual servos, and an ultrasonic sensor. It implements an automated material handling workflow featuring autonomous locomotion, object detection stopping, and robotic arm pick-and-place manipulation. The content illustrates multi-degree-of-freedom kinematics in robotic arms alongside worm gear transmission mechanics. It covers sequential timing choreography and multi-mechanism coordination logic. Furthermore, it examines core engineering design concepts behind multi-functional collaborative operations in industrial robotics.</p><img loading="lazy" height="1662" width="1662" src="'+l+'" class="common_img" style="width:400px;"><h2 id="_3-44-2-learning-objectives" tabindex="-1">3.44.2 Learning Objectives <a class="header-anchor" href="#_3-44-2-learning-objectives" aria-label="Permalink to &quot;3.44.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand multi-degree-of-freedom kinematics achieved through dual-servo coordination. Master worm gear mechanical properties, including speed reduction, torque multiplication, and self-locking characteristics. Recognize tracked chassis drive methods and terrain adaptability. Understand linked control logic for ultrasonic-triggered automated grasping.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical structure of the tank robotic arm independently, mastering zero-point calibration during dual-servo installation. Construct gripper open-and-close control routines and encapsulate them into custom functions. Implement a complete sequential handling workflow combining ultrasonic detection stopping, grasping, lifting, rotating, and releasing.</p></li><li><p><strong>Thinking Objectives</strong>: Build mechanical system thinking centered on multi-degree-of-freedom coordination, and understand sequential timing choreography among multiple actuators. Cultivate algorithmic workflow thinking for motion sequence planning. Reinforce engineering methodologies of decomposing complex systems into manageable sequential stages.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to practical applications including articulated industrial robots, assembly line manipulators, overhead cranes, and hydraulic excavators. Appreciate the critical value of industrial robotics in automated manufacturing. Inspire exploration into robotics engineering, industrial automation, and mechanical transmission design.</p></li></ol><h2 id="_3-44-3-preparation" tabindex="-1">3.44.3 Preparation <a class="header-anchor" href="#_3-44-3-preparation" aria-label="Permalink to &quot;3.44.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>180° block servo</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Small building block object for grasping</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab graphical programming platform</li></ul><h2 id="_3-44-4-hands-on-project" tabindex="-1">3.44.4 Hands-On Project <a class="header-anchor" href="#_3-44-4-hands-on-project" aria-label="Permalink to &quot;3.44.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Tank Robotic Arm, delivering a complete industrial handling sequence that autonomously approaches, detects, and sequentially manipulates targets. The system employs an architecture combining tracked mobility, ultrasonic detection, and multi-mechanism sequential execution. The tracked chassis motor drives the robot forward until the ultrasonic sensor measures a clearance of less than 20 cm, triggering a complete stop. Four actuation units work in coordination: motor S1 drives a worm gear to actuate the gripper, servo S2 controls arm pitch, servo S3 manages base rotation, and motor S4 powers tracked locomotion. The control routine executes a precise motion sequence: lower to position, close gripper, lift cargo, rotate base, lower to deposit, and reset. Once material transfer completes, the robot resumes forward travel, modeling the operational workflow of automated industrial manipulators.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),x(s,{src:"../../_static/shared/pdf/chapter_3/44.pdf"}),t[1]||(t[1]=n('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the gripper-drive 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the arm-pitch 180° block servo to port <strong>S2</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the base-rotation 180° block servo to port <strong>S3</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the tracked-chassis 360° block motor to port <strong>S4</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1763" width="2490" src="'+q+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+P+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+A+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="155" width="413" src="'+a+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="77" src="'+i+'"></td><td style="text-align:left;">Create a custom function without parameters to encapsulate reusable program logic.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="155" width="413" src="'+a+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="77" src="'+i+'"></td><td style="text-align:left;">Call a defined parameterless function to execute all encapsulated program statements.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Serve as the main program loop container, continuously executing internal code after power-on initialization.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Execute only once after startup to initialize hardware configurations and system parameters.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="151" width="345" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Detect the real-time electrical state of a specified button, returning a Boolean value to determine whether the button is pressed.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="495" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+r+'"></td><td style="text-align:left;">Initialize the hardware connection port for the ultrasonic sensor.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="658" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+r+'"></td><td style="text-align:left;">Retrieve obstacle distance data measured by the ultrasonic sensor in centimeters (cm).</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Drive the 360° block motor at a designated port to rotate continuously at a customized speed in the forward or reverse direction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+u+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Stop power output to the 360° block motor at the designated port, immediately halting motor rotation.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+f+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Control the 180° block servo at the designated port to rotate for a specified duration at a customized speed. In non-blocking mode, the program proceeds immediately to subsequent blocks without waiting for motion completion.</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="511" width="431" src="'+z+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the hardware port for the ultrasonic sensor. Next, it defines a custom function to control the gripper. When Button B on the right is pressed, motor S1 reverses at 20% speed to close the gripper. When Button A on the left is pressed, motor S1 rotates forward at 20% speed to open the gripper. When neither button is pressed, motor S1 halts, repeating until both buttons are pressed simultaneously to exit the subroutine. After powering on, the tank robotic arm advances continuously until an obstacle is detected within 20 cm, prompting a complete stop. Holding the right button closes the gripper around the target. Once the object is securely clamped, pressing both buttons simultaneously initiates the arm sequence: lifting, rotating, and lowering. Pressing the left button then opens the gripper to deposit the item.</p></li></ul><img loading="lazy" height="1485" width="896" src="'+T+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+b+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1adJTOnyve2MmEehrB9YFSW8echTWwoF2?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-44-5-expansion-and-challenge" tabindex="-1">3.44.5 Expansion and Challenge <a class="header-anchor" href="#_3-44-5-expansion-and-challenge" aria-label="Permalink to &quot;3.44.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Fully Autonomous Unmanned Manipulation Arm</strong></p><p>Calibrate gripper travel duration using worm gear rotation times, applying an open-loop delay of 0.8 s to stop the motor automatically upon closing rather than relying on manual button presses. Practice timing calibration and open-loop control while appreciating mechanical self-locking reliability. Extend discussions to unmanned industrial articulated arms and automated assembly line robots.</p><p><strong>Project 2: Multi-Target Continuous Transfer Robotic Arm</strong></p><p>Utilize an integer variable to log completed transfer cycles, programming the tracked base to reverse to its starting point after each deposit to locate the next target. Practice position recovery and multi-cycle execution logic while understanding batch workflow management. Extend discussions to warehouse automated guided vehicles, logistics sorting systems, and flexible manufacturing cells.</p><h2 id="_3-44-6-q-a" tabindex="-1">3.44.6 Q&amp;A <a class="header-anchor" href="#_3-44-6-q-a" aria-label="Permalink to &quot;3.44.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the robotic arm require two servos rather than one, and what specific role does each servo perform?</strong></p><p>Answer: The two servos control <strong>two distinct directional degrees of freedom</strong>, both of which are essential for material handling. Servo S2 governs arm pitch, raising and lowering the arm vertically like an elbow joint bending and extending to adjust cargo elevation. Servo S3 governs base rotation, pivoting the entire arm horizontally like a waist turning from side to side to transfer cargo between pickup and drop-off coordinates. A system with only pitch motion can only move vertically in place. A system with only rotational motion can change headings but cannot elevate cargo. Coordinating both degrees of freedom enables the manipulator to access multiple spatial points, reaching forward to grasp an object and turning laterally to deposit it. Industrial articulated robots often feature six or seven degrees of freedom, which are vastly more complex. However, the underlying principle remains identical: each actuator manages an individual joint axis, and coordinated multi-joint motion allows the end effector to reach any spatial position and orientation. Increasing degrees of freedom enhances dexterity, but also increases kinematic control complexity.</p><p><strong>Question 2: Why does the gripper utilize a worm gear mechanism rather than direct servo actuation?</strong></p><p>Answer: A worm gear mechanism delivers two critical engineering advantages over direct servo drives. The first advantage is <strong>speed reduction and torque multiplication</strong>. Because the worm must make numerous revolutions to turn the worm gear a single rotation, output speed decreases while mechanical torque multiplies substantially. This mechanical advantage allows a compact motor to exert strong clamping forces capable of securing heavy objects. The second advantage is <strong>reverse self-locking</strong>. Motion transmits exclusively from the worm screw to the worm gear. External forces applied to the worm gear cannot backdrive the worm screw. Once the gripper clamps an object, it remains tightly locked even if motor power is completely cut off, preventing cargo from slipping loose. Direct servo actuation generates relatively low holding torque, and unpowered servos can be backdriven by external loads, risking accidental drops. Self-locking is essential across heavy engineering applications such as overhead hoists and screw jacks to guarantee load stability without continuous power consumption. Integrating a worm gear mechanism ensures that the gripper maintains powerful, secure clamping.</p><h2 id="_3-44-7-technical-support-and-product-discussion" tabindex="-1">3.44.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-44-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.44.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Submit questions or share project modifications in the community forum:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+y+'" class="common_img" style="width:800px;"></a>',31))])}const Z=_(S,[["render",j]]);export{Y as __pageData,Z as default};
